rule "omni-v5-ti-eset-hash"
when
  to_string($message.event_source) == "eset" &&
  has_field("eset_hash") &&
  !is_null(lookup_value("omni-v5-ti-hachage", lowercase(to_string($message.eset_hash))))
then
  let v = regex("^([^|]*)\\|([^|]*)\\|([^|]*)\\|([^|]*)\\|([^|]*)\\|([^|]*)\\|(.*)$", to_string(lookup_value("omni-v5-ti-hachage", lowercase(to_string($message.eset_hash)))), ["s","t","m","c","p","f","r"]);
  set_field("ti_match", lowercase(to_string($message.eset_hash)));
  set_field("ti_source", v["s"]);
  set_field("ti_type", v["t"]);
  set_field("ti_malware", v["m"]);
  set_field("ti_confiance", v["c"]);
  set_field("ti_ioc_date", v["f"]);
  set_field("ti_ref", v["r"]);
  set_field("ti_tag", "omni_v5_ti");
  set_field("ti_contexte", "eset");
end

